  rr(c, -15, -6, 30, 12, 5);
  c.fill();
  c.fillStyle = shade(car.color, -30);
  rr(c, -7, -4.5, 13, 9, 3);
  c.fill();
  c.fillStyle = 'rgba(219, 237, 213, .55)';
  rr(c, -5, -3.5, 9, 7, 2);
  c.fill();
