function drawPadBase(c, layout, pad) {
  const r = layout.padRadius;
  c.save();
  c.translate(pad.x, pad.y + 4);
  c.fillStyle = 'rgba(44, 23, 15, .22)';
  c.beginPath();
  c.ellipse(2, 4, r + 5, r * .76, 0, 0, TAU);
  c.fill();
  c.restore();

  c.beginPath();
  c.arc(pad.x, pad.y, r, 0, TAU);
  c.fillStyle = '#805237';
  c.fill();
  c.strokeStyle = '#5a3826';
  c.lineWidth = 2.4;
  c.stroke();

  c.beginPath();
  c.arc(pad.x, pad.y, r - 5, 0, TAU);
  c.fillStyle = '#6c4530';
  c.fill();

  c.save();
  c.setLineDash([5, 6]);
  c.beginPath();
  c.arc(pad.x, pad.y, r - 10, 0, TAU);
  c.strokeStyle = 'rgba(242, 208, 148, .62)';
  c.lineWidth = 1.6;
  c.stroke();
  c.restore();

  c.strokeStyle = 'rgba(248, 217, 159, .3)';
  c.lineWidth = 1.4;
  for (let i = 0; i < 4; i++) {
    const a = i * TAU / 4 + Math.PI / 4;
    c.beginPath();
    c.moveTo(pad.x + Math.cos(a) * (r - 17), pad.y + Math.sin(a) * (r - 17));
    c.lineTo(pad.x + Math.cos(a) * (r - 8), pad.y + Math.sin(a) * (r - 8));
    c.stroke();
  }

  c.save();
  c.translate(pad.x + r * .48, pad.y + r * .38);
  c.rotate(-.2);
  c.fillStyle = '#c47e4b';
  rr(c, -9, -3, 9, 5, 1.5);
  c.fill();
  c.fillStyle = '#d9965d';
  rr(c, 0, -5, 9, 5, 1.5);
  c.fill();
  c.fillStyle = '#b46b42';
  rr(c, -4, -8, 9, 5, 1.5);
  c.fill();
  c.restore();
}

function drawRiftBase(c, layout, rift) {
  const angle = Math.atan2(layout.core.y - rift.y, layout.core.x - rift.x);
  c.save();
  c.translate(rift.x, rift.y);
  c.rotate(angle);

  c.fillStyle = 'rgba(50, 17, 28, .26)';
  c.beginPath();
  c.ellipse(0, 0, 56, 30, 0, 0, TAU);
  c.fill();

  c.beginPath();
  c.moveTo(-34, -13);
  c.lineTo(-17, -22);
  c.lineTo(-2, -15);
  c.lineTo(15, -25);
  c.lineTo(36, -10);
  c.lineTo(20, 0);
  c.lineTo(35, 15);
  c.lineTo(9, 18);
  c.lineTo(-8, 25);
  c.lineTo(-22, 11);
  c.lineTo(-37, 17);
  c.lineTo(-28, 2);
  c.closePath();
  c.fillStyle = '#291d20';
  c.fill();
  c.strokeStyle = 'rgba(255, 89, 132, .28)';
  c.lineWidth = 2;
  c.stroke();

  c.beginPath();
  c.ellipse(-2, 2, 22, 10, 0, 0, TAU);
  c.fillStyle = '#140f14';
  c.fill();
  c.strokeStyle = 'rgba(255, 94, 141, .76)';
  c.lineWidth = 1.5;
  c.stroke();

  c.strokeStyle = 'rgba(255, 94, 141, .42)';
  c.lineWidth = 1.4;
  for (let i = 0; i < 4; i++) {
    c.beginPath();
    const sx = -17 + i * 12;
    c.moveTo(sx, 1);
    c.lineTo(sx - 8, -10 - i * 3);
    c.lineTo(sx - 14, -13 - i * 5);
    c.stroke();
  }
  c.restore();
}

function drawPlaza(c, layout) {
  const { x, y, r } = layout.core;
  c.save();
  c.fillStyle = 'rgba(53, 29, 19, .2)';
  c.beginPath();
  c.ellipse(x + 3, y + 16, r + 45, (r + 42) * .55, 0, 0, TAU);
  c.fill();

  c.beginPath();
  c.arc(x, y, r + 39, 0, TAU);
  c.fillStyle = '#d9ba85';
  c.fill();
  c.strokeStyle = '#a77d55';
  c.lineWidth = 3;
  c.stroke();

  c.beginPath();
  c.arc(x, y, r + 29, 0, TAU);
  c.fillStyle = '#e7cca0';
  c.fill();
  c.strokeStyle = 'rgba(155, 111, 73, .5)';
  c.lineWidth = 1.3;
  c.stroke();

  const segments = 18;
  for (let i = 0; i < segments; i++) {
    const a = i * TAU / segments;
    c.beginPath();
    c.moveTo(x + Math.cos(a) * (r + 3), y + Math.sin(a) * (r + 3));
    c.lineTo(x + Math.cos(a) * (r + 27), y + Math.sin(a) * (r + 27));
    c.strokeStyle = i % 3 === 0 ? 'rgba(151, 104, 67, .36)' : 'rgba(151, 104, 67, .18)';
    c.lineWidth = 1;
    c.stroke();
  }

  for (let i = 0; i < 4; i++) {
    const a = i * TAU / 4 + Math.PI / 4;
    const px = x + Math.cos(a) * (r + 31);
    const py = y + Math.sin(a) * (r + 31);
    c.save();
    c.translate(px, py);
    c.rotate(a + Math.PI / 2);
    c.fillStyle = 'rgba(59, 35, 23, .25)';
    c.beginPath();
    c.ellipse(0, 4, 8, 3, 0, 0, TAU);
    c.fill();
    c.strokeStyle = '#69523d';
    c.lineWidth = 2;
    c.beginPath();
    c.moveTo(0, 1);
    c.lineTo(0, -20);
    c.stroke();
    c.fillStyle = '#bc6347';
    c.beginPath();
    c.moveTo(1, -20);
    c.quadraticCurveTo(10, -18, 11, -12);
    c.quadraticCurveTo(5, -13, 1, -11);
    c.closePath();
    c.fill();
    c.restore();
  }

  c.restore();
}

function drawTexture(c, layout) {
  const rand = seeded(7101);
  for (let i = 0; i < 760; i++) {
    const x = 24 + rand() * (layout.w - 48);
    const y = 22 + rand() * (layout.h - 44);
    const size = .5 + rand() * 1.6;
    c.globalAlpha = .025 + rand() * .07;
    c.fillStyle = rand() > .5 ? '#2f1c14' : '#ffe0a9';
    c.beginPath();
    c.arc(x, y, size, 0, TAU);
    c.fill();
  }
  c.globalAlpha = 1;

  c.save();
  c.strokeStyle = 'rgba(60, 32, 21, .13)';
  c.lineWidth = 1.2;
  for (let i = 0; i < 13; i++) {
    const x = 35 + rand() * (layout.w - 70);
    const y = 28 + rand() * (layout.h - 56);
    if (Math.hypot(x - layout.core.x, y - layout.core.y) < 120) continue;
    c.beginPath();
    c.moveTo(x, y);
    c.lineTo(x + 7 + rand() * 12, y + 4);
    c.lineTo(x + 13 + rand() * 9, y - 3);
    c.stroke();
  }
  c.restore();
}

export function buildBoard(layout) {
  if (layout._boardCanvas) return layout._boardCanvas;
  const c = document.createElement('canvas');
  c.width = layout.w * BOARD_SCALE;
  c.height = layout.h * BOARD_SCALE;
  const g = c.getContext('2d');
  g.scale(BOARD_SCALE, BOARD_SCALE);

  drawBoardSurface(g, layout);
  drawRoads(g, layout);

  for (const car of layout.cars) drawCar(g, car);
  for (const lamp of layout.lamps) drawLamp(g, lamp);

  const accepted = [];
  const sorted = [...layout.buildings].sort((a, b) => (a.y + a.h) - (b.y + b.h));
  for (let i = 0; i < sorted.length; i++) {
    const b = sorted[i];
    if (!buildingClear(layout, b, accepted)) continue;
    accepted.push(b);
    drawBuilding(g, b, i);
  }

  drawCrane(g, layout.crane);
  drawPlaza(g, layout);
  for (const tree of layout.trees) drawTree(g, tree);

  for (const pad of layout.pads) drawPadBase(g, layout, pad);
  for (const rift of layout.rifts) drawRiftBase(g, layout, rift);

  drawTexture(g, layout);
  layout._boardCanvas = c;
  return c;
}

export function paintTable(c, width, height) {
  const rand = seeded(812);
  const bg = c.createRadialGradient(width * .5, height * .42, 10, width * .5, height * .5, Math.max(width, height) * .78);
  bg.addColorStop(0, '#19443d');
  bg.addColorStop(.45, '#0f2d28');
  bg.addColorStop(.8, '#081d1a');
  bg.addColorStop(1, '#041210');
  c.fillStyle = bg;
  c.fillRect(0, 0, width, height);

  c.save();
  c.globalCompositeOperation = 'screen';
  const glow = c.createRadialGradient(width * .5, height * .34, 0, width * .5, height * .36, width * .45);
  glow.addColorStop(0, 'rgba(255, 173, 102, .10)');
  glow.addColorStop(.55, 'rgba(59, 150, 126, .035)');
  glow.addColorStop(1, 'rgba(0, 0, 0, 0)');
  c.fillStyle = glow;
  c.fillRect(0, 0, width, height);
  c.restore();

  c.save();
  c.globalAlpha = .08;
  c.strokeStyle = '#8fb59c';
  c.lineWidth = 1;
  for (let i = 0; i < 22; i++) {
    const y = rand() * height;
    c.beginPath();
    c.moveTo(0, y);
    c.bezierCurveTo(width * .3, y + rand() * 20 - 10, width * .7, y + rand() * 22 - 11, width, y + rand() * 12 - 6);
    c.stroke();
  }
  c.restore();

  for (let i = 0; i < 70; i++) {
    const x = rand() * width;
    const y = rand() * height;
    if (x > width * .15 && x < width * .85 && y > height * .08 && y < height * .92) continue;
    c.globalAlpha = .05 + rand() * .12;
    c.fillStyle = rand() > .6 ? '#db9a63' : '#afc6aa';
    c.beginPath();
    c.ellipse(x, y, 1 + rand() * 3, .6 + rand() * 1.7, rand() * TAU, 0, TAU);
    c.fill();
  }
  c.globalAlpha = 1;

  c.save();
  const vignette = c.createRadialGradient(width * .5, height * .48, Math.min(width, height) * .3, width * .5, height * .5, Math.max(width, height) * .72);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0)');
  vignette.addColorStop(.74, 'rgba(0, 0, 0, .12)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, .48)');
  c.fillStyle = vignette;
  c.fillRect(0, 0, width, height);
  c.restore();
}

export function drawCore(c, layout, time, healthRatio, flash) {
  const { x, y } = layout.core;
  const pulse = .5 + .5 * Math.sin(time * 2.1);
  const r = layout.core.r;

  c.save();
  c.globalCompositeOperation = 'lighter';
  const glow = c.createRadialGradient(x, y - 8, 5, x, y - 8, 105);
  glow.addColorStop(0, `rgba(255, 198, 93, ${.19 + pulse * .1})`);
  glow.addColorStop(.55, 'rgba(255, 138, 69, .045)');
  glow.addColorStop(1, 'rgba(255, 138, 69, 0)');
  c.fillStyle = glow;
  c.beginPath();
  c.arc(x, y - 8, 108, 0, TAU);
  c.fill();
  c.restore();

  c.save();
  c.translate(x, y + 2);
  c.fillStyle = 'rgba(49, 25, 16, .28)';
  c.beginPath();
  c.ellipse(0, 34, 48, 14, 0, 0, TAU);
  c.fill();

  c.fillStyle = '#bf8454';
  rr(c, -36, 21, 72, 18, 7);
  c.fill();
  c.fillStyle = '#dba56c';
  rr(c, -33, 22, 66, 6, 3);
  c.fill();
  c.fillStyle = '#9d6240';
  rr(c, -30, 30, 60, 8, 4);
  c.fill();

  const beat = 1 + Math.sin(time * 2.2) * .035;
  c.translate(0, -1);
  c.scale(beat, beat);

  const heart = (scale) => {
    c.beginPath();
    c.moveTo(0, 38 * scale);
    c.bezierCurveTo(34 * scale, 13 * scale, 35 * scale, -24 * scale, 10 * scale, -25 * scale);
    c.bezierCurveTo(2 * scale, -25 * scale, 0, -19 * scale, 0, -14 * scale);
    c.bezierCurveTo(0, -19 * scale, -2 * scale, -25 * scale, -10 * scale, -25 * scale);
    c.bezierCurveTo(-35 * scale, -24 * scale, -34 * scale, 13 * scale, 0, 38 * scale);
    c.closePath();
  };

  c.shadowColor = 'rgba(255, 147, 77, .5)';
  c.shadowBlur = 24;
  heart(1.05);
  c.fillStyle = '#a9452f';
  c.fill();
  c.shadowBlur = 0;

  heart(1);
  const hg = c.createLinearGradient(-25, -25, 20, 35);
  hg.addColorStop(0, '#ff9c66');
  hg.addColorStop(.48, '#e46543');
  hg.addColorStop(1, '#bd4934');
  c.fillStyle = hg;
  c.fill();
  c.strokeStyle = 'rgba(88, 34, 24, .54)';
  c.lineWidth = 2;
  c.stroke();

  c.beginPath();
  c.ellipse(-11, -8, 8, 5, -.55, 0, TAU);
  c.fillStyle = 'rgba(255, 226, 180, .42)';
  c.fill();

  c.fillStyle = 'rgba(98, 38, 27, .52)';
  if (healthRatio < .7) {
    c.beginPath();
    c.moveTo(-8, 24);
    c.lineTo(-12, 13);
    c.lineTo(-5, 7);
    c.lineTo(-8, -2);
    c.strokeStyle = 'rgba(84, 29, 21, .55)';
    c.lineWidth = 2;
    c.stroke();
  }
  if (healthRatio < .4) {
    c.beginPath();
    c.moveTo(19, 10);
    c.lineTo(14, 1);
    c.lineTo(21, -7);
    c.strokeStyle = 'rgba(84, 29, 21, .55)';
    c.lineWidth = 1.8;
    c.stroke();
  }

  c.globalAlpha = .78;
  c.fillStyle = '#ffd374';
  c.beginPath();
  c.arc(-8, -2, 2.2, 0, TAU);
  c.arc(8, -2, 2.2, 0, TAU);
  c.fill();
  c.restore();

  const ringR = r + 42;
  c.save();
  c.strokeStyle = 'rgba(39, 23, 17, .26)';
  c.lineWidth = 5;
  c.beginPath();
  c.arc(x, y, ringR, 0, TAU);
  c.stroke();
  c.strokeStyle = healthRatio > .35 ? '#5ad6b8' : '#ff8068';
  c.lineWidth = 3;
  c.lineCap = 'round';
  c.beginPath();
  c.arc(x, y, ringR, -Math.PI / 2, -Math.PI / 2 + TAU * healthRatio);
  c.stroke();
  c.restore();

  if (flash > 0) {
    c.save();
    c.globalAlpha = flash * .52;
    c.globalCompositeOperation = 'screen';
    c.fillStyle = '#ff8f7d';
    c.beginPath();
    c.arc(x, y - 2, 88, 0, TAU);
    c.fill();
    c.restore();
  }
}

export function drawPadGlow(c, layout, pad, time, active, valid) {
  const r = layout.padRadius;
  c.save();
  c.translate(pad.x, pad.y);
  const pulse = .5 + .5 * Math.sin(time * 3 + pad.i);
  if (active) {
    c.globalAlpha = .28 + pulse * .2;
    c.strokeStyle = valid ? '#ffe08a' : '#ff7b82';
    c.lineWidth = 2;
    c.setLineDash([5, 6]);
    c.beginPath();
    c.arc(0, 0, r + 6 + pulse * 3, time * .5, TAU + time * .5);
    c.stroke();
    c.setLineDash([]);
    c.globalAlpha = .75 + pulse * .25;
    c.fillStyle = valid ? '#ffe3a0' : '#ff9b9b';
    c.font = '900 15px Nunito, sans-serif';
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText('+', 0, -1);
  } else if (valid) {
    c.globalAlpha = .08 + pulse * .04;
    c.fillStyle = '#ffe08a';
    c.beginPath();
    c.arc(0, 0, r + 2, 0, TAU);
    c.fill();
  }
  c.restore();
}

export function drawRiftGlow(c, layout, rift, time) {
  const a = Math.atan2(layout.core.y - rift.y, layout.core.x - rift.x);
  c.save();
  c.translate(rift.x, rift.y);
  c.rotate(a);
  c.globalCompositeOperation = 'lighter';
  const pulse = .5 + .5 * Math.sin(time * 2.3 + rift.x * .02);
  const g = c.createRadialGradient(0, 0, 2, 0, 0, 55);
  g.addColorStop(0, `rgba(255, 73, 126, ${.18 + pulse * .09})`);
  g.addColorStop(1, 'rgba(255, 73, 126, 0)');
  c.fillStyle = g;
  c.beginPath();
  c.ellipse(0, 0, 58, 32, 0, 0, TAU);
  c.fill();
  c.restore();
}

export function drawRange(c, x, y, range, color = '#67e5cb', time = 0, valid = true) {
  c.save();
  c.translate(x, y);
  c.globalAlpha = .08;
  c.fillStyle = valid ? color : '#ff6d7e';
  c.beginPath();
  c.arc(0, 0, range, 0, TAU);
  c.fill();
  c.globalAlpha = .52;
  c.strokeStyle = valid ? color : '#ff6d7e';
  c.lineWidth = 1.5;
  c.setLineDash([6, 9]);
  c.lineDashOffset = -time * 12;
  c.beginPath();
  c.arc(0, 0, range, 0, TAU);
  c.stroke();
  c.setLineDash([]);
  c.globalAlpha = .34;
  c.beginPath();
  c.arc(0, 0, range - 4, 0, TAU);
  c.strokeStyle = 'rgba(255,255,255,.45)';
  c.lineWidth = .7;
  c.stroke();
  c.restore();
}

export function drawHealthPips(c, layout, coreHp, maxHp) {
  c.save();
  c.translate(layout.core.x, layout.core.y + layout.core.r + 64);
  const count = 10;
  for (let i = 0; i < count; i++) {
    const x = (i - (count - 1) / 2) * 10;
    const on = (i + 1) / count <= coreHp / maxHp + .0001;
    c.fillStyle = on ? '#f2c36f' : 'rgba(47, 26, 18, .28)';
    c.beginPath();
    c.arc(x, 0, 2.6, 0, TAU);
    c.fill();
  }
  c.restore();
}

export function drawTargetReticle(c, x, y, radius, time) {
  c.save();
  c.translate(x, y);
  c.rotate(time * .6);
  c.strokeStyle = '#ffd478';
  c.globalAlpha = .9;
  c.lineWidth = 2;
  c.setLineDash([8, 7]);
  c.beginPath();
  c.arc(0, 0, radius, 0, TAU);
  c.stroke();
  c.setLineDash([]);
  c.globalAlpha = .35;
  c.fillStyle = '#ffd478';
  c.beginPath();
  c.arc(0, 0, radius, 0, TAU);
  c.fill();
  c.rotate(-time * 1.2);
  for (let i = 0; i < 4; i++) {
    c.rotate(Math.PI / 2);
    c.beginPath();
    c.moveTo(radius - 13, 0);
    c.lineTo(radius + 2, 0);
    c.stroke();
  }
  c.restore();
}

export function drawSpawnPulse(c, layout, time) {
  for (let i = 0; i < layout.rifts.length; i++) {
    const rift = layout.rifts[i];
    const a = Math.atan2(layout.core.y - rift.y, layout.core.x - rift.x);
    const pulse = (time * .5 + i * .5) % 1;
    c.save();
    c.translate(rift.x, rift.y);
    c.rotate(a);
    c.globalAlpha = (1 - pulse) * .3;
    c.strokeStyle = '#ff6188';
    c.lineWidth = 1.5;
    c.beginPath();
    c.ellipse(0, 0, 30 + pulse * 28, 14 + pulse * 12, 0, 0, TAU);
    c.stroke();
    c.restore();
  }
}

import { TAU, TOWERS, rr, shade, rgba } from './util.js';

function shadow(c, rx = 19, ry = 7, y = 6) {
  c.fillStyle = 'rgba(44, 24, 16, .26)';
  c.beginPath();
  c.ellipse(2, y, rx, ry, 0, 0, TAU);
  c.fill();
}

function drawEyes(c, x, y, gap, color = '#2f1b14') {
  c.fillStyle = color;
  c.beginPath();
  c.arc(x - gap, y, 1.8, 0, TAU);
  c.arc(x + gap, y, 1.8, 0, TAU);
  c.fill();
  c.fillStyle = 'rgba(255, 240, 200, .8)';
  c.beginPath();
  c.arc(x - gap + .55, y - .55, .55, 0, TAU);
  c.arc(x + gap + .55, y - .55, .55, 0, TAU);
  c.fill();
}

function drawLevelRing(c, level, time, accent) {
  if (!level || level < 1) return;
  c.save();
  c.globalAlpha = .8;
  c.strokeStyle = accent;
  c.lineWidth = 1.2;
  c.beginPath();
  c.arc(0, 2, 27, .16, Math.PI - .16);
  c.stroke();
  for (let i = 0; i < level; i++) {
    const a = Math.PI * .78 + i * .44;
    c.fillStyle = accent;
    c.beginPath();
    c.arc(Math.cos(a) * 27, 2 + Math.sin(a) * 27, 1.7, 0, TAU);
    c.fill();
  }
  c.restore();
}

function drawSlinger(c, level, angle, recoil, time) {
  const bob = Math.sin(time * 2.1) * .9;
  c.save();
  c.translate(0, bob);

  c.fillStyle = '#78503b';
  rr(c, -8, -4, 6, 8, 3);
  c.fill();
  rr(c, 2, -4, 6, 8, 3);
  c.fill();

  const body = c.createLinearGradient(-14, -29, 13, -7);
  body.addColorStop(0, level > 2 ? '#ffc47f' : '#eeb66a');
  body.addColorStop(.55, level > 2 ? '#e89e5d' : '#d99453');
  body.addColorStop(1, '#a95e3e');
  c.beginPath();
  c.ellipse(0, -17, 15, 16, -.05, 0, TAU);
  c.fillStyle = body;
  c.fill();
  c.strokeStyle = 'rgba(80, 39, 25, .5)';
  c.lineWidth = 1.3;
  c.stroke();

  c.beginPath();
  c.ellipse(-5, -24, 5.5, 4, -.6, 0, TAU);
  c.fillStyle = 'rgba(255, 231, 183, .42)';
  c.fill();

  drawEyes(c, 0, -20, 4.3);
  c.strokeStyle = '#542e22';
  c.lineWidth = 1.2;
  c.beginPath();
  c.arc(0, -15, 3.8, .25, Math.PI - .25);
  c.stroke();

  c.strokeStyle = '#9b5d3d';
  c.lineWidth = 4.2;
  c.lineCap = 'round';
  c.beginPath();
  c.moveTo(-11, -13);
  c.lineTo(-18, -8);
  c.stroke();

  c.save();
  c.translate(5, -20);
  c.rotate(angle);
  c.translate(-recoil * 3.5, 0);
  c.fillStyle = '#804a32';
  rr(c, -2, -4.6, 23, 9, 4);
  c.fill();
  c.fillStyle = '#d99250';
  rr(c, 0, -4, 17, 7, 3);
  c.fill();
  c.fillStyle = '#c57846';
  c.beginPath();
  c.arc(21, 0, 4.8, 0, TAU);
  c.fill();
  c.fillStyle = '#5b3425';
  c.beginPath();
  c.arc(21, 0, 2.2, 0, TAU);
  c.fill();
  c.fillStyle = '#f4cf8b';
  c.beginPath();
  c.arc(18, -1.3, 1.4, 0, TAU);
  c.fill();
  c.restore();

  if (level > 1) {
    c.strokeStyle = '#5d8f7e';
    c.lineWidth = 2.2;
    c.beginPath();
    c.moveTo(-13, -26);
    c.quadraticCurveTo(-19, -19, -12, -12);
    c.stroke();
    c.fillStyle = '#71d6bd';
    c.beginPath();
    c.moveTo(14, -28);
    c.lineTo(19, -34);
    c.lineTo(20, -25);
    c.closePath();
    c.fill();
  }

  if (level > 2) {
    c.fillStyle = '#ffd477';
    for (let i = 0; i < 3; i++) {
      const a = -.9 + i * .9;
      c.beginPath();
      c.moveTo(Math.cos(a) * 14, -17 + Math.sin(a) * 14);
      c.lineTo(Math.cos(a) * 22, -17 + Math.sin(a) * 22);
      c.lineTo(Math.cos(a + .16) * 14, -17 + Math.sin(a + .16) * 14);
      c.closePath();
      c.fill();
    }
  }

  c.restore();
}

function drawMortar(c, level, angle, recoil, time) {
  const bob = Math.sin(time * 1.75 + .7) * .7;
  c.save();
  c.translate(0, bob);

  c.fillStyle = '#754a32';
  rr(c, -11, -4, 8, 9, 3);
  c.fill();
  rr(c, 3, -4, 8, 9, 3);
  c.fill();

  const body = c.createLinearGradient(-18, -26, 16, -2);
  body.addColorStop(0, '#d8a269');
  body.addColorStop(.5, '#bd7e4e');
  body.addColorStop(1, '#8c553a');
  rr(c, -18, -24, 36, 22, 10);
  c.fillStyle = body;
  c.fill();
  c.strokeStyle = 'rgba(74, 35, 22, .48)';
  c.lineWidth = 1.4;
  c.stroke();

  c.fillStyle = 'rgba(255, 224, 173, .35)';
  c.beginPath();
  c.ellipse(-7, -21, 7, 3.5, -.25, 0, TAU);
  c.fill();

  drawEyes(c, 0, -17, 5.2);
  c.strokeStyle = '#60382a';
