}

function drawGoo(c, level, angle, recoil, time) {
  const bob = Math.sin(time * 2 + 1.8) * .7;
  c.save();
  c.translate(0, bob);

  c.globalCompositeOperation = 'lighter';
  const glow = c.createRadialGradient(0, -18, 2, 0, -18, 26);
  glow.addColorStop(0, 'rgba(153, 226, 105, .2)');
  glow.addColorStop(1, 'rgba(153, 226, 105, 0)');
  c.fillStyle = glow;
  c.beginPath();
  c.arc(0, -18, 26, 0, TAU);
  c.fill();
  c.globalCompositeOperation = 'source-over';

  c.fillStyle = '#62452f';
  rr(c, -12, -3, 7, 8, 2);
  c.fill();
  rr(c, 5, -3, 7, 8, 2);
  c.fill();

  const pot = c.createLinearGradient(-17, -26, 16, -4);
  pot.addColorStop(0, '#a8b468');
  pot.addColorStop(.45, '#7d9757');
  pot.addColorStop(1, '#526a3f');
  c.beginPath();
  c.moveTo(-18, -22);
  c.quadraticCurveTo(-21, -6, 0, -3);
  c.quadraticCurveTo(21, -6, 18, -22);
  c.closePath();
  c.fillStyle = pot;
  c.fill();
  c.strokeStyle = 'rgba(53, 54, 31, .55)';
  c.lineWidth = 1.3;
  c.stroke();

  c.beginPath();
  c.ellipse(0, -22, 18, 8, 0, 0, TAU);
  c.fillStyle = '#415633';
  c.fill();
  c.beginPath();
  c.ellipse(0, -22, 14, 5.3, 0, 0, TAU);
  c.fillStyle = '#9ddb65';
  c.fill();
  c.beginPath();
  c.ellipse(-4, -23, 8, 2.5, -.2, 0, TAU);
  c.fillStyle = 'rgba(211, 255, 155, .65)';
  c.fill();

  for (let i = 0; i < 3; i++) {
    const a = time * 1.8 + i * 2.1;
    const bx = Math.cos(a) * (3 + i * 4);
    const by = -23 - Math.sin(a) * (2 + i);
    c.beginPath();
    c.arc(bx, by, 1.2 + (i % 2) * .7, 0, TAU);
    c.fillStyle = '#c9f58a';
    c.fill();
  }

  drawEyes(c, 0, -14, 5, '#24321f');
  c.strokeStyle = '#344629';
  c.lineWidth = 1.2;
  c.beginPath();
  c.arc(0, -10, 3.5, .3, Math.PI - .3);
  c.stroke();

  c.save();
  c.translate(11, -18);
  c.rotate(angle);
  c.translate(-recoil * 3, 0);
  c.fillStyle = '#6d7d4b';
  rr(c, -2, -3.4, 17, 6.8, 3);
  c.fill();
  c.fillStyle = '#b8e478';
  c.beginPath();
  c.arc(16, 0, 3.5, 0, TAU);
  c.fill();
  c.restore();

  c.strokeStyle = '#5b6e40';
  c.lineWidth = 2.2;
  c.beginPath();
  c.arc(-17, -14, 5, .5, 2.7);
  c.stroke();
  c.beginPath();
  c.arc(17, -14, 5, -2.7, -.5);
  c.stroke();

  if (level > 1) {
    c.fillStyle = '#d7ff94';
    for (let i = 0; i < level; i++) {
      c.beginPath();
      c.arc(-12 + i * 12, -5, 1.25, 0, TAU);
      c.fill();
    }
  }

  if (level > 2) {
    c.fillStyle = '#e6c36d';
    c.beginPath();
    c.arc(0, -27, 2.4, 0, TAU);
    c.fill();
    c.strokeStyle = 'rgba(255, 235, 162, .65)';
    c.lineWidth = 1;
    c.beginPath();
    c.arc(0, -27, 5.5, 0, TAU);
    c.stroke();
  }

  c.restore();
}

function drawKiln(c, level, angle, recoil, time) {
  const pulse = .5 + .5 * Math.sin(time * 3.2);
  c.save();
  c.translate(0, Math.sin(time * 1.8 + 2.2) * .45);

  c.globalCompositeOperation = 'lighter';
  const glow = c.createRadialGradient(0, -26, 2, 0, -26, 32);
  glow.addColorStop(0, `rgba(255, 143, 78, ${.12 + pulse * .08})`);
  glow.addColorStop(1, 'rgba(255, 143, 78, 0)');
  c.fillStyle = glow;
  c.beginPath();
  c.arc(0, -26, 32, 0, TAU);
  c.fill();
  c.globalCompositeOperation = 'source-over';

  c.fillStyle = '#704532';
  rr(c, -11, -3, 7, 8, 2);
  c.fill();
  rr(c, 4, -3, 7, 8, 2);
  c.fill();

  const body = c.createLinearGradient(-16, -52, 15, -3);
  body.addColorStop(0, '#dd8b62');
  body.addColorStop(.45, '#bd654b');
  body.addColorStop(1, '#8e4838');
  c.beginPath();
  c.moveTo(-13, -53);
  c.quadraticCurveTo(-19, -44, -17, -5);
  c.quadraticCurveTo(0, 3, 17, -5);
  c.quadraticCurveTo(19, -44, 13, -53);
  c.closePath();
  c.fillStyle = body;
  c.fill();
  c.strokeStyle = 'rgba(68, 29, 22, .5)';
  c.lineWidth = 1.4;
  c.stroke();

  c.fillStyle = '#e8a47b';
  rr(c, -14, -56, 28, 7, 3);
  c.fill();
  c.fillStyle = '#8c4b39';
  rr(c, -9, -60, 18, 5, 2);
  c.fill();

  c.strokeStyle = 'rgba(82, 37, 27, .28)';
  c.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    c.beginPath();
    c.moveTo(-13 + i * 7, -51);
    c.lineTo(-12 + i * 7, -8);
    c.stroke();
  }

  c.save();
  c.globalCompositeOperation = 'lighter';
  c.strokeStyle = `rgba(255, 187, 89, ${.4 + pulse * .4})`;
  c.lineWidth = 1.6;
  c.beginPath();
  c.moveTo(-8, -37);
  c.lineTo(-3, -30);
  c.lineTo(-7, -23);
  c.lineTo(0, -17);
  c.stroke();
  c.beginPath();
  c.moveTo(10, -14);
  c.lineTo(7, -21);
  c.lineTo(12, -27);
  c.stroke();
  c.restore();

  c.beginPath();
  c.ellipse(0, -18, 7, 5.3, 0, 0, TAU);
  c.fillStyle = '#45281f';
  c.fill();
  c.fillStyle = `rgba(255, 178, 70, ${.5 + pulse * .4})`;
  c.beginPath();
  c.arc(-2.6, -18, 1.2, 0, TAU);
  c.arc(2.6, -18, 1.2, 0, TAU);
  c.fill();

  c.save();
  c.translate(0, -30);
  c.rotate(angle);
  c.translate(-recoil * 4, 0);
  c.fillStyle = '#71422f';
  rr(c, 4, -5.5, 20, 11, 4);
  c.fill();
  c.fillStyle = '#c36a4a';
  rr(c, 5, -4, 16, 8, 3);
  c.fill();
  c.fillStyle = '#ffb459';
  c.beginPath();
  c.arc(22, 0, 3.2, 0, TAU);
  c.fill();
  c.restore();

  c.fillStyle = 'rgba(255, 182, 101, .38)';
  for (let i = 0; i < 3; i++) {
    const t = (time * .55 + i * .33) % 1;
    c.globalAlpha = (1 - t) * .45;
    c.beginPath();
    c.arc(-4 + i * 4, -62 - t * 18, 2 + t * 3, 0, TAU);
    c.fill();
  }
  c.globalAlpha = 1;

  if (level > 1) {
    c.strokeStyle = '#f3c36c';
    c.lineWidth = 1.3;
    c.beginPath();
    c.arc(0, -6, 13.5, .15, Math.PI - .15);
    c.stroke();
  }
  if (level > 2) {
    c.fillStyle = '#ffd376';
    c.beginPath();
    c.moveTo(-14, -53);
    c.lineTo(-19, -62);
    c.lineTo(-10, -57);
    c.closePath();
    c.fill();
    c.beginPath();
    c.moveTo(14, -53);
    c.lineTo(19, -62);
    c.lineTo(10, -57);
    c.closePath();
    c.fill();
  }

  c.restore();
}

export function drawTowerArt(c, type, level = 1, angle = -.4, recoil = 0, time = 0, scale = 1) {
  const def = TOWERS[type];
  c.save();
  c.scale(scale, scale);
  shadow(c, type === 'kiln' ? 17 : 19, 6.5, 6);
  c.save();
  if (type === 'slinger') drawSlinger(c, level, angle, recoil, time);
  else if (type === 'mortar') drawMortar(c, level, angle, recoil, time);
  else if (type === 'goo') drawGoo(c, level, angle, recoil, time);
  else drawKiln(c, level, angle, recoil, time);
  c.restore();
  drawLevelRing(c, level, time, def.accent);
  c.restore();
}

export function drawTower(c, tower, time, selected = false) {
  const bob = Math.sin(time * 2 + tower.seed) * .5;
  c.save();
  c.translate(tower.x, tower.y + bob);
  if (tower.scaleIn < 1) {
    const s = Math.max(.01, tower.scaleIn);
    c.scale(s, s);
  }
  if (selected) {
    c.save();
    c.strokeStyle = 'rgba(255, 212, 118, .85)';
    c.lineWidth = 1.6;
    c.setLineDash([5, 7]);
    c.lineDashOffset = -time * 12;
    c.beginPath();
    c.arc(0, 4, 30, 0, TAU);
    c.stroke();
    c.restore();
  }
  drawTowerArt(c, tower.type, tower.level, tower.angle, tower.recoil, time, 1);
  if (tower.rally > 0) {
    c.save();
    c.globalCompositeOperation = 'lighter';
    const r = 20 + Math.sin(time * 4) * 4;
    c.strokeStyle = `rgba(255, 209, 110, ${.22 + Math.sin(time * 5) * .08})`;
    c.lineWidth = 2;
    c.beginPath();
    c.arc(0, -13, r, 0, TAU);
    c.stroke();
    c.restore();
  }
  c.restore();
}

export function drawTowerIcon(canvas, type, level = 1) {
  const c = canvas.getContext('2d');
  const size = canvas.width;
  c.clearRect(0, 0, size, size);
  const scale = size / 96;
  c.save();
  c.translate(size * .5, size * .80);
  c.scale(scale * 1.45, scale * 1.45);
  if (type === 'kiln') c.translate(0, 7);
  drawTowerArt(c, type, level, -.52, 0, 1.2, 1);
  c.restore();
}

export function drawTowerAura(c, x, y, color = '#ffd36d') {
  c.save();
  c.translate(x, y);
  c.globalCompositeOperation = 'lighter';
  const g = c.createRadialGradient(0, -8, 2, 0, -8, 38);
  g.addColorStop(0, rgba(color, .16));
  g.addColorStop(1, rgba(color, 0));
  c.fillStyle = g;
  c.beginPath();
  c.arc(0, -8, 38, 0, TAU);
  c.fill();
  c.restore();
}

import { TAU, ENEMIES, clamp } from './util.js';

function bodyGradient(c, x0, y0, x1, y1, color, top = 20) {
  const g = c.createLinearGradient(x0, y0, x1, y1);
  g.addColorStop(0, color);
  g.addColorStop(.55, color);
  g.addColorStop(1, 'rgba(52, 26, 21, .9)');
  return g;
}

function enemyShadow(c, rx, ry, y) {
  c.fillStyle = 'rgba(34, 17, 12, .25)';
  c.beginPath();
  c.ellipse(2, y, rx, ry, 0, 0, TAU);
  c.fill();
}

function drawLegs(c, phase, spread, y, color, length = 7) {
  const swing = Math.sin(phase) * 3.2;
  c.fillStyle = color;
  c.save();
  c.translate(-spread, y);
  c.rotate(swing * .07);
  c.beginPath();
  c.ellipse(0, length * .5, 3.2, length * .65, .08, 0, TAU);
  c.fill();
  c.restore();
  c.save();
  c.translate(spread, y);
  c.rotate(-swing * .07);
  c.beginPath();
  c.ellipse(0, length * .5, 3.2, length * .65, -.08, 0, TAU);
  c.fill();
  c.restore();
}

function drawEyes(c, y, gap, size = 2.1, color = '#ff5f88') {
  c.save();
  c.globalCompositeOperation = 'lighter';
  c.fillStyle = 'rgba(255, 63, 113, .32)';
  c.beginPath();
  c.arc(-gap, y, size * 2.3, 0, TAU);
  c.arc(gap, y, size * 2.3, 0, TAU);
  c.fill();
  c.restore();
  c.fillStyle = color;
  c.beginPath();
  c.arc(-gap, y, size, 0, TAU);
  c.arc(gap, y, size, 0, TAU);
  c.fill();
  c.fillStyle = '#ffe6e8';
  c.beginPath();
  c.arc(-gap + .55, y - .7, size * .34, 0, TAU);
  c.arc(gap + .55, y - .7, size * .34, 0, TAU);
  c.fill();
}

