}

function drawBoss(c, e, phase, time) {
  const pulse = .5 + .5 * Math.sin(time * 2.8);
  c.save();
  c.globalCompositeOperation = 'lighter';
  const aura = c.createRadialGradient(0, -40, 8, 0, -40, 76);
  aura.addColorStop(0, `rgba(255, 69, 131, ${.14 + pulse * .07})`);
  aura.addColorStop(1, 'rgba(255, 69, 131, 0)');
  c.fillStyle = aura;
  c.beginPath();
  c.arc(0, -40, 76, 0, TAU);
  c.fill();
  c.restore();

  c.strokeStyle = `rgba(255, 88, 140, ${.26 + pulse * .18})`;
  c.lineWidth = 1.7;
  c.beginPath();
  c.arc(0, 2, 31 + pulse * 4, 0, TAU);
  c.stroke();

  drawLegs(c, phase, 14, -2, '#5f2f42', 12);

  const body = c.createLinearGradient(-28, -58, 26, -2);
  body.addColorStop(0, '#a65b7b');
  body.addColorStop(.55, '#84435f');
  body.addColorStop(1, '#572d42');
  c.fillStyle = body;
  c.beginPath();
  c.moveTo(-27, -44);
  c.quadraticCurveTo(-31, -16, -18, -5);
  c.quadraticCurveTo(0, 3, 18, -5);
  c.quadraticCurveTo(31, -16, 27, -44);
  c.quadraticCurveTo(17, -59, 0, -58);
  c.quadraticCurveTo(-17, -59, -27, -44);
  c.fill();
  c.strokeStyle = 'rgba(45, 20, 30, .55)';
  c.lineWidth = 1.6;
  c.stroke();

  c.fillStyle = '#71364f';
  c.beginPath();
  c.arc(-28, -38, 11, 0, TAU);
  c.arc(28, -38, 11, 0, TAU);
  c.fill();
  c.fillStyle = '#9b5370';
  c.beginPath();
  c.ellipse(-27, -17, 10, 15, .38, 0, TAU);
  c.ellipse(27, -17, 10, 15, -.38, 0, TAU);
  c.fill();

  c.fillStyle = '#6c354c';
  c.beginPath();
  c.ellipse(0, -66, 14, 12, 0, 0, TAU);
  c.fill();
  c.fillStyle = '#b56c85';
  c.beginPath();
  c.ellipse(0, -64, 11.5, 9, 0, 0, TAU);
  c.fill();

  drawEyes(c, -65, 5, 2.2, '#ff4c8c');
  c.fillStyle = '#3b1422';
  c.beginPath();
  c.moveTo(-9, -56);
  c.lineTo(-4, -52);
  c.lineTo(0, -56);
  c.lineTo(4, -52);
  c.lineTo(9, -56);
  c.lineTo(5, -49);
  c.lineTo(0, -53);
  c.lineTo(-5, -49);
  c.closePath();
  c.fill();

  c.save();
  c.globalCompositeOperation = 'lighter';
  c.strokeStyle = `rgba(255, 79, 135, ${.4 + pulse * .5})`;
  c.lineWidth = 1.8;
  c.beginPath();
  c.moveTo(-17, -40);
  c.lineTo(-9, -31);
  c.lineTo(-13, -20);
  c.lineTo(-4, -12);
  c.stroke();
  c.beginPath();
  c.moveTo(17, -33);
  c.lineTo(10, -24);
  c.lineTo(15, -14);
  c.stroke();
  c.restore();

  c.fillStyle = '#5e2d42';
  for (let i = 0; i < 5; i++) {
    const a = -Math.PI + i * (Math.PI / 4);
    const x = Math.cos(a) * 16;
    const y = -80 + Math.sin(a) * 6;
    c.beginPath();
    c.moveTo(x, y);
    c.lineTo(x + Math.cos(a) * 10, y - 11 - (i % 2) * 5);
    c.lineTo(x + Math.cos(a + .2) * 8, y + 3);
    c.closePath();
    c.fill();
  }

  c.strokeStyle = 'rgba(255, 200, 109, .8)';
  c.lineWidth = 1.2;
  c.beginPath();
  c.arc(0, -66, 14.5, Math.PI * 1.08, Math.PI * 1.92);
  c.stroke();
  c.restore();
}

function drawHealthBar(c, e, def, height) {
  if (e.hp >= e.maxHp && !def.boss) return;
  const boss = def.boss;
  const w = boss ? 66 : 28;
  const y = -height - (boss ? 17 : 8);
  c.save();
  c.fillStyle = 'rgba(8, 17, 14, .76)';
  rr(c, -w / 2, y, w, boss ? 5.5 : 3.6, 3);
  c.fill();
  const ratio = clamp(e.hp / e.maxHp, 0, 1);
  const color = ratio > .55 ? '#68d9a6' : ratio > .25 ? '#f0bd5f' : '#ff6c78';
  c.fillStyle = color;
  rr(c, -w / 2 + .8, y + .8, Math.max(0, (w - 1.6) * ratio), (boss ? 5.5 : 3.6) - 1.6, 2);
  c.fill();
  if (boss) {
    c.fillStyle = '#ffb26b';
    c.font = '900 6px Nunito, sans-serif';
    c.textAlign = 'center';
    c.fillText('THE AUDITOR', 0, y - 5);
  }
  c.restore();
}

export function drawEnemy(c, e, time, gameTime) {
  const def = ENEMIES[e.type];
  const phase = e.walkPhase || 0;
  const stunned = (e.stunUntil || 0) > gameTime;
  const slowed = (e.slowUntil || 0) > gameTime;
  const hit = e.hitFlash || 0;
  const heights = { runt: 33, runner: 38, brute: 56, splitter: 39, boss: 86 };
  const height = heights[e.type] || 35;
  const bob = stunned ? Math.sin(time * 9) * .4 : Math.sin(phase * 2) * 1.2;

  c.save();
  c.translate(e.x, e.y);

  const shadowScale = e.type === 'boss' ? 1.7 : e.type === 'brute' ? 1.3 : 1;
  enemyShadow(c, 12 * shadowScale, 4.5 * shadowScale, 4);

  if (slowed) {
    c.fillStyle = 'rgba(120, 203, 84, .2)';
    c.beginPath();
    c.ellipse(0, 3, 16, 6, 0, 0, TAU);
    c.fill();
    c.strokeStyle = 'rgba(163, 235, 111, .42)';
    c.lineWidth = 1;
    c.setLineDash([3, 4]);
    c.beginPath();
    c.arc(0, 3, 18, 0, TAU);
    c.stroke();
    c.setLineDash([]);
  }

  if (hit > 0) {
    c.save();
    c.globalCompositeOperation = 'screen';
    c.globalAlpha = hit * .35;
    c.fillStyle = '#ffd0ac';
    c.beginPath();
    c.arc(0, -height * .45, height * .56, 0, TAU);
    c.fill();
    c.restore();
  }

  c.translate(0, bob);
  if (e.type === 'runt') drawRunt(c, e, phase);
  else if (e.type === 'runner') drawRunner(c, e, phase);
  else if (e.type === 'brute') drawBrute(c, e, phase);
  else if (e.type === 'splitter') drawSplitter(c, e, phase);
  else drawBoss(c, e, phase, time);

  if (stunned) {
    c.save();
    c.translate(0, -height - 4);
    for (let i = 0; i < 3; i++) {
      const a = time * 4 + i * TAU / 3;
      const x = Math.cos(a) * 13;
      const y = Math.sin(a) * 4;
      c.fillStyle = 'rgba(255, 218, 111, .9)';
      c.beginPath();
      for (let k = 0; k < 5; k++) {
        const sa = -Math.PI / 2 + k * TAU / 5;
        const px = x + Math.cos(sa) * 3;
        const py = y + Math.sin(sa) * 3;
        if (k === 0) c.moveTo(px, py);
        else c.lineTo(px, py);
      }
      c.closePath();
      c.fill();
    }
    c.restore();
  }

  if (e.type === 'splitter') {
    const pulse = .5 + .5 * Math.sin(time * 3 + e.seed);
    c.strokeStyle = `rgba(210, 255, 134, ${.22 + pulse * .2})`;
    c.lineWidth = 1;
    c.beginPath();
    c.arc(0, -19, 22 + pulse * 2, 0, TAU);
    c.stroke();
  }

  c.restore();
  drawHealthBar(c, e, def, height);
}

export function drawEnemyDeathMark(c, x, y, time) {
  c.save();
  c.translate(x, y);
  c.globalAlpha = .3;
  c.fillStyle = '#4b2b23';
  c.beginPath();
  c.ellipse(0, 0, 12, 4, 0, 0, TAU);
  c.fill();
  c.restore();
}

import { TAU, clamp, rgba, rr } from './util.js';

export function drawProjectile(c, p, time) {
  if (!p) return;
  const z = p.z || 0;

  if (z > .5) {
    c.save();
    c.globalAlpha = .18 + Math.min(.32, z / 110);
    c.fillStyle = '#201611';
    c.beginPath();
    c.ellipse(p.x, p.y, 5 + z * .035, 2.5 + z * .015, 0, 0, TAU);
    c.fill();
    c.restore();
  }

  const x = p.x;
  const y = p.y - z;
  const angle = p.angle || 0;

  if (p.kind === 'pebble') {
    c.save();
    c.strokeStyle = 'rgba(245, 201, 123, .3)';
    c.lineWidth = 2;
    c.lineCap = 'round';
    c.beginPath();
    c.moveTo(x - Math.cos(angle) * 13, y - Math.sin(angle) * 13);
    c.lineTo(x, y);
    c.stroke();
    c.fillStyle = '#f3cc82';
    c.beginPath();
    c.arc(x, y, 2.8, 0, TAU);
    c.fill();
    c.fillStyle = 'rgba(255, 241, 198, .85)';
    c.beginPath();
    c.arc(x - .7, y - .8, 1, 0, TAU);
    c.fill();
    c.restore();
  } else if (p.kind === 'goo') {
    c.save();
    c.strokeStyle = 'rgba(167, 229, 104, .34)';
    c.lineWidth = 3;
    c.lineCap = 'round';
    c.beginPath();
    c.moveTo(x - Math.cos(angle) * 14, y - Math.sin(angle) * 14);
    c.lineTo(x, y);
    c.stroke();
    c.fillStyle = '#a6da63';
    c.beginPath();
    c.arc(x, y, 4.4, 0, TAU);
    c.fill();
    c.fillStyle = '#dcff97';
    c.beginPath();
    c.arc(x - 1, y - 1, 1.6, 0, TAU);
    c.fill();
    c.restore();
  } else if (p.kind === 'mortar') {
    c.save();
    c.fillStyle = '#b37b54';
    c.beginPath();
    c.arc(x, y, 6.2, 0, TAU);
    c.fill();
    c.strokeStyle = 'rgba(76, 41, 27, .45)';
    c.lineWidth = 1;
    c.stroke();
    c.fillStyle = '#e1b37d';
    c.beginPath();
    c.arc(x - 1.8, y - 2, 2.1, 0, TAU);
    c.fill();
    c.globalAlpha = .4;
    c.fillStyle = '#593726';
    for (let i = 0; i < 2; i++) {
      c.beginPath();
      c.arc(x + 7 + i * 4, y + 1 - i * 2, 1.4 + i, 0, TAU);
      c.fill();
    }
    c.restore();
  } else {
    c.save();
    c.fillStyle = '#ffd06a';
    c.beginPath();
    c.arc(x, y, 3.8, 0, TAU);
    c.fill();
    c.restore();
  }
}

export function drawEffect(c, e, time) {
  const life = clamp(e.life / e.maxLife, 0, 1);
  if (e.type === 'ring') {
    const t = 1 - life;
    const radius = e.r0 + (e.r1 - e.r0) * (1 - Math.pow(1 - t, 2));
    c.save();
    c.globalAlpha = life * (e.alpha == null ? .72 : e.alpha);
    c.strokeStyle = e.color || '#ffd36d';
    c.lineWidth = e.width || 2;
    c.beginPath();
    c.arc(e.x, e.y, radius, 0, TAU);
    c.stroke();
    if (e.fill) {
      c.globalAlpha = life * .08;
      c.fillStyle = e.color;
      c.beginPath();
      c.arc(e.x, e.y, radius, 0, TAU);
      c.fill();
    }
    c.restore();
  } else if (e.type === 'beam') {
    c.save();
    c.globalCompositeOperation = 'lighter';
    const alpha = life;
    c.strokeStyle = rgba(e.color || '#ffbb5c', alpha * .16);
    c.lineWidth = (e.width || 10) * 2.2;
    c.lineCap = 'round';
    c.beginPath();
    c.moveTo(e.x1, e.y1);
    c.lineTo(e.x2, e.y2);
    c.stroke();
    c.strokeStyle = rgba(e.color || '#ffbb5c', alpha * .72);
    c.lineWidth = e.width || 8;
    c.stroke();
    c.strokeStyle = rgba('#fff3ce', alpha * .9);
    c.lineWidth = Math.max(1, (e.width || 8) * .28);
    c.stroke();
    c.restore();
  } else if (e.type === 'splash') {
    const t = 1 - life;
    const r = (e.radius || 30) * (.35 + t * .85);
    c.save();
    c.globalAlpha = life * .55;
    c.fillStyle = e.color || '#b87d52';
    c.beginPath();
    c.arc(e.x, e.y, r, 0, TAU);
    c.fill();
    c.globalAlpha = life * .8;
    c.strokeStyle = e.color || '#b87d52';
    c.lineWidth = 2;
    c.beginPath();
    c.arc(e.x, e.y, r, 0, TAU);
    c.stroke();
    c.restore();
  } else if (e.type === 'quake') {
    const t = 1 - life;
    for (let i = 0; i < 3; i++) {
      const rr2 = 22 + (e.radius || 100) * (t * .85 + i * .07);
      c.save();
      c.globalAlpha = life * (.52 - i * .12);
      c.strokeStyle = e.color || '#ffd36d';
      c.lineWidth = 2.2 - i * .4;
      c.beginPath();
      c.arc(e.x, e.y, rr2, 0, TAU);
      c.stroke();
      c.restore();
    }
    c.save();
    c.globalAlpha = life * .7;
    c.strokeStyle = '#4f2b1c';
    c.lineWidth = 1.6;
    const cracks = e.cracks || [];
    for (const crack of cracks) {
      c.beginPath();
      c.moveTo(e.x + crack[0], e.y + crack[1]);
      for (let i = 1; i < crack.length; i += 2) {
        c.lineTo(e.x + crack[i], e.y + crack[i + 1]);
      }
      c.stroke();
    }
    c.restore();
  } else if (e.type === 'flash') {
    c.save();
    c.globalCompositeOperation = 'screen';
    c.globalAlpha = life * .5;
    const g = c.createRadialGradient(e.x, e.y, 1, e.x, e.y, e.radius || 40);
    g.addColorStop(0, e.color || '#ffd36d');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    c.fillStyle = g;
    c.beginPath();
    c.arc(e.x, e.y, e.radius || 40, 0, TAU);
    c.fill();
    c.restore();
  } else if (e.type === 'slamMark') {
    const t = 1 - life;
    c.save();
    c.translate(e.x, e.y);
    c.rotate(t * .08);
    c.globalAlpha = life * .45;
    c.strokeStyle = '#3d2317';
    c.lineWidth = 1.5;
    for (let i = 0; i < 8; i++) {
      c.rotate(TAU / 8);
      c.beginPath();
      c.moveTo(10, 0);
      c.lineTo(26 + t * 28, -2);
      c.lineTo(40 + t * 20, 2);
      c.stroke();
    }
    c.restore();
  }
}

export function drawParticle(c, p) {
  const life = clamp(p.life / p.maxLife, 0, 1);
  if (life <= 0) return;
  c.save();
  c.globalAlpha = life * (p.alpha == null ? 1 : p.alpha);
  if (p.kind === 'smoke') {
    c.fillStyle = p.color;
    c.beginPath();
    c.arc(p.x, p.y, p.size * (1.4 - life * .4), 0, TAU);
    c.fill();
  } else if (p.kind === 'shard') {
    c.translate(p.x, p.y);
    c.rotate(p.rot || 0);
    c.fillStyle = p.color;
    rr(c, -p.size * .7, -p.size * .4, p.size * 1.4, p.size * .8, .8);
    c.fill();
  } else {
    c.fillStyle = p.color;
    c.beginPath();
    c.arc(p.x, p.y, p.size * life, 0, TAU);
    c.fill();
  }
  c.restore();
}

export function drawFloatText(c, t) {
  const life = clamp(t.life / t.maxLife, 0, 1);
  c.save();
  c.globalAlpha = Math.min(1, life * 1.9);
  c.fillStyle = t.color || '#ffd47c';
  c.font = `900 ${t.size || 11}px Nunito, sans-serif`;
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.shadowColor = 'rgba(0,0,0,.5)';
  c.shadowBlur = 3;
  c.fillText(t.text, t.x, t.y - (1 - life) * 22);
  c.restore();
}

export function drawMote(c, m) {
  c.save();
  c.globalAlpha = m.alpha;
  c.fillStyle = m.color;
  c.beginPath();
  c.arc(m.x, m.y, m.size, 0, TAU);
  c.fill();
  c.restore();
}

