+  dom.inspector.classList.add('show');
+  dom.btnInspectClose.focus({ preventScroll: true });
+  Sound.play('click');
+  updateHUD();
+}
+
+function dismissSelection() {
+  selectedTower = null;
+  selectedBuild = null;
+  if (game) game.targetMode = null;
+  dom.inspector.classList.remove('show');
+  updateHUD();
+}
+
+function tryBuild(pad) {
