  await sleep(300);
  const afterMobile = await snap(page);
  ok('tap-build works on phone portrait', afterMobile.towers === beforeMobile + 1 || afterMobile.money === 0, `${beforeMobile} -> ${afterMobile.towers}, money ${afterMobile.money}, pt ${JSON.stringify(mpt)}`);

  // landscape phone
  await page.setViewportSize({ width: 844, height: 390 });
  await sleep(600);
  const land = await page.evaluate(() => ({ w: window.__clayfront.layout.w, h: window.__clayfront.layout.h, dockH: document.querySelector('#dock').getBoundingClientRect().height, topH: document.querySelector('#hud .topbar').getBoundingClientRect().height }));
  ok('landscape layout selected', land.w === 1280 && land.h === 800, JSON.stringify(land));
  ok('dock stays usable on short screen', land.dockH < 390 * .5, `dock ${Math.round(land.dockH)}`);
  await page.screenshot({ path: 'screenshots/mobile-landscape.png' });

  // defeat flow
  await page.setViewportSize({ width: 1440, height: 900 });
  await sleep(500);
  await page.evaluate(() => window.__clayfront.damageCore(999));
  await sleep(600);
  ok('defeat result shown', await page.locator('#resultOverlay').isVisible() && /lost/i.test(await page.getAttribute('#resultOverlay', 'class')));
  ok('defeat title', /DEFEAT|LOST|BROKEN/i.test(await page.textContent('#resultTitle')), await page.textContent('#resultTitle'));
  await page.screenshot({ path: 'screenshots/desktop-defeat.png' });

  // restart
  await page.click('#btnAgain');
  await sleep(500);
  s = await snap(page);
  ok('play again resets run', s.mode === 'playing' && s.coreHp === 20 && s.towers === 0 && s.money === 240, JSON.stringify(s));

  const realErrors = errors.filter(e => !/favicon/i.test(e));
  ok('no console/page errors (excluding favicon)', realErrors.length === 0, realErrors.slice(0, 4).join(' | '));

  console.log('\nSUMMARY', results.filter(r => r.pass).length + '/' + results.length, 'passed');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

