const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(300);

  const info = async (label) => {
    const d = await page.evaluate(() => {
      const g = window.__clayfront.state;
      return {
        selBuild: g ? null : null,
        targetMode: g.targetMode, towers: g.towers.map(t => ({ pad: t.pad, type: t.type, x: t.x, y: t.y, lvl: t.level })),
        inspector: document.querySelector('#inspector').className,
        cards: [...document.querySelectorAll('.tower-card')].map(c => c.classList.contains('active')),
        money: g.money
      };
    });
    console.log(label, JSON.stringify(d));
  };

  const pt = async (i) => page.evaluate((i) => {
    const l = window.__clayfront.layout; const pad = l.pads[i];
    const r = document.querySelector('canvas').getBoundingClientRect();
    const scale = Math.min(r.width / l.w, r.height / l.h);
    const ox = (r.width - l.w * scale) / 2, oy = (r.height - l.h * scale) / 2;
    return { x: pad.x * scale + ox + r.left, y: pad.y * scale + oy + r.top, pad, scale, ox, oy };
  }, i);

  await info('initial');
  await page.locator('.tower-card').nth(0).click();
  await sleep(100);
  await info('after select card');
  const p0 = await pt(0);
  console.log('pad0 screen', p0);
  await page.mouse.click(p0.x, p0.y);
  await sleep(250);
  await info('after build pad0');

  const p1 = await pt(1);
  console.log('pad1 screen', p1);
  await page.mouse.click(p1.x, p1.y);
  await sleep(250);
  await info('after click pad1');

  // dispatch pointerdown direct
  await page.evaluate(({x,y}) => {
    const c = document.querySelector('canvas');
    c.dispatchEvent(new PointerEvent('pointermove', {clientX:x,clientY:y,button:0,buttons:0,bubbles:true,pointerId:1,pointerType:'mouse'}));
    c.dispatchEvent(new PointerEvent('pointerdown', {clientX:x,clientY:y,button:0,buttons:1,bubbles:true,pointerId:1,pointerType:'mouse'}));
  }, p1);
  await sleep(250);
  await info('after dispatch pad1');

  await page.screenshot({ path: 'screenshots/debug-click.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

