const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(300);
  const pt = async (i) => page.evaluate((i) => {
    const l = window.__clayfront.layout; const pad = l.pads[i];
    const r = document.querySelector('canvas').getBoundingClientRect();
    const scale = Math.min(r.width / l.w, r.height / l.h);
    const ox = (r.width - l.w * scale) / 2, oy = (r.height - l.h * scale) / 2;
    return { x: pad.x * scale + ox + r.left, y: pad.y * scale + oy + r.top, pad };
  }, i);
  const build = async (type, pad) => {
    const idx = { slinger: 0, mortar: 1, goo: 2, kiln: 3 }[type];
    const card = page.locator('.tower-card').nth(idx);
    if (!(await card.evaluate(el => el.classList.contains('active')))) await card.click();
    await sleep(80);
    const p = await pt(pad);
    await page.mouse.click(p.x, p.y);
    await sleep(220);
  };
  const dump = async (label) => {
    const d = await page.evaluate(() => {
      const g = window.__clayfront.state;
      return { mode: g.mode, phase: g.phase, target: g.targetMode, towers: g.towers.map(t => ({ pad: t.pad, type: t.type })), inspector: document.querySelector('#inspector').className, cards: [...document.querySelectorAll('.tower-card')].map(c => c.classList.contains('active')), money: g.money, qcd: g.quakeCd, rcd: g.rallyCd };
    });
    console.log(label, JSON.stringify(d));
  };
  for (const [type, pad] of [['slinger', 0], ['slinger', 1], ['goo', 2], ['slinger', 4]]) await build(type, pad);
  await dump('built');
  await page.mouse.click(720, 540);
  await sleep(120);
  await dump('deselect');

  await page.click('#btnWave');
  await sleep(2600);
  await page.click('#btnSpeed');
  await page.click('#btnPause');
  await sleep(150);
  await page.click('#btnResume');
  await sleep(200);
  await page.click('#btnHelp');
  await sleep(150);
  await page.click('#btnHowDone');
  await sleep(150);
  await dump('before abilities');

  await page.click('#abilitySlam');
  const pq = await pt(7);
  console.log('quake pt', pq, 'elementAt', await page.evaluate(({x,y}) => { const el = document.elementFromPoint(x,y); return el.tagName + '#' + el.id + '.' + el.className; }, pq));
  await page.mouse.click(pq.x, pq.y);
  await sleep(250);
  await dump('after quake');
  await page.click('#abilityRally');
  await sleep(250);
  await dump('after rally');

  const p1 = await pt(1);
  const at = await page.evaluate(({x,y}) => { const el = document.elementFromPoint(x,y); return el.tagName + '#' + el.id + '.' + el.className; }, p1);
  console.log('pad1 pt', p1, 'elementAt', at);
  await page.evaluate(() => window.__clayfront.setClay(300));
  await page.mouse.click(p1.x, p1.y);
  await sleep(300);
  await dump('after click pad1');
  await page.screenshot({ path: 'screenshots/debug-click2.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

