const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(300);
  const pt = async (i) => page.evaluate((i) => {
    const l = window.__clayfront.layout; const pad = l.pads[i];
    const r = document.querySelector('canvas').getBoundingClientRect();
    const scale = Math.min(r.width / l.w, r.height / l.h);
    return { x: pad.x * scale + r.left, y: pad.y * scale + r.top };
  }, i);
  const build = async (idx, pad) => {
    const card = page.locator('.tower-card').nth(idx);
    if (!(await card.evaluate(el => el.classList.contains('active')))) await card.click();
    const p = await pt(pad); await page.mouse.click(p.x, p.y); await sleep(180);
  };
  await build(0, 0); await build(0, 1); await build(2, 2); await build(0, 4);
  console.log('towers', await page.evaluate(() => window.__clayfront.state.towers.length));
  await page.click('#btnWave');
  await page.click('#btnSpeed');
  for (let i = 0; i < 8; i++) {
    await sleep(2500);
    const d = await page.evaluate(() => {
      const g = window.__clayfront.state;
      return {
        t: Math.round(g.elapsed * 10) / 10, money: g.money, kills: g.kills, core: g.coreHp, enemies: g.enemies.length, projectiles: g.projectiles.length,
        e: g.enemies.slice(0, 4).map(e => ({ type: e.type, hp: Math.round(e.hp), x: Math.round(e.x), y: Math.round(e.y), dist: Math.round(e.dist) })),
        tw: g.towers.map(t => ({ pad: t.pad, x: t.x, y: t.y, cd: Math.round(t.attackCd * 10) / 10, hasTarget: !!t.target, inRange: t.target ? Math.round(Math.hypot(t.target.x - t.x, t.target.y - t.y)) : null }))
      };
    });
    console.log(JSON.stringify(d));
  }
  await page.screenshot({ path: 'screenshots/combat.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

