const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function run(strategyName, buildFn) {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(200);
  await page.evaluate(() => window.__clayfront.fastForward(0.1));
  const log = [];
  await page.evaluate(buildFn, 'initial');
  for (let wave = 1; wave <= 10; wave++) {
    const before = await page.evaluate(() => window.__clayfront.stateSnapshot());
    if (before.mode === 'ended') break;
    await page.evaluate(() => window.__clayfront.startWave());
    let secs = 0;
    let st = before;
    while (secs < 120) {
      await page.evaluate(() => window.__clayfront.fastForward(2));
      secs += 2;
      st = await page.evaluate(() => window.__clayfront.stateSnapshot());
      if (st.mode !== 'playing' || st.phase !== 'active') break;
    }
    log.push({ wave, secs, core: st.coreHp, money: st.money, kills: st.kills, towers: st.towers, mode: st.mode, idx: st.waveIndex });
    console.log(strategyName, JSON.stringify(log[log.length - 1]));
    if (st.mode === 'ended') break;
    if (st.phase === 'prep') await page.evaluate(buildFn, 'buy');
  }
  const final = await page.evaluate(() => ({
    state: window.__clayfront.stateSnapshot(),
    result: document.querySelector('#resultTitle').textContent,
    resultVisible: !document.querySelector('#resultOverlay').classList.contains('hidden'),
    errors: []
  }));
  console.log(strategyName, 'FINAL', JSON.stringify(final), 'errors', errors.slice(0, 3));
  await browser.close();
  return { log, final, errors };
}

const allSlingers = async (phase) => {
  const f = window.__clayfront;
  const order = [1, 2, 6, 7, 4, 5, 8, 9, 0, 3, 10, 11];
  let acted = true;
  while (acted) {
    acted = false;
    for (const pad of order) {
      const has = f.state.towers.some(t => t.pad === pad);
      if (!has && f.state.money >= 50) { f.place('slinger', pad); acted = true; }
    }
    const t = f.state.towers.find(t => t.level < 3);
    if (t) {
      const cost = t.level === 1 ? 41 : 65;
      if (f.state.money >= cost) { f.upgrade(t.pad); acted = true; }
    }
    if (f.state.towers.length >= 12 && f.state.towers.every(t => t.level >= 3)) break;
  }
};

(async () => {
  await run('SLINGERS', allSlingers);
})().catch(e => { console.error('FATAL', e); process.exit(1); });

