const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function sim(name, buyScript) {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(150);
  const logs = [];
  await page.evaluate(buyScript, 'initial');
  for (let wave = 1; wave <= 10; wave++) {
    const b = await page.evaluate(() => window.__clayfront.stateSnapshot());
    if (b.mode === 'ended') break;
    await page.evaluate(() => window.__clayfront.startWave());
    let secs = 0, st = b;
    while (secs < 120) {
      await page.evaluate(() => window.__clayfront.fastForward(2));
      secs += 2;
      st = await page.evaluate(() => window.__clayfront.stateSnapshot());
      if (st.mode !== 'playing' || st.phase !== 'active') break;
    }
    logs.push(`w${wave} core${st.coreHp} kills${st.kills} money${st.money} tw${st.towers}${st.mode === 'ended' ? ' END' : ''}`);
    if (st.mode === 'ended') break;
    if (st.phase === 'prep') await page.evaluate(buyScript, 'buy');
  }
  const res = await page.evaluate(() => ({ t: document.querySelector('#resultTitle').textContent, v: !document.querySelector('#resultOverlay').classList.contains('hidden'), s: window.__clayfront.stateSnapshot() }));
  console.log(name, '|', logs.join(' | '), '| RESULT', JSON.stringify(res));
  await browser.close();
}

const fourSlingers = async () => {
  const f = window.__clayfront;
  if (!f.state.towers.length) for (const pad of [1, 2, 6, 7]) f.place('slinger', pad);
};
const sixSlingersL2 = async () => {
  const f = window.__clayfront;
  const pads = [1, 2, 6, 7, 4, 5];
  if (!f.state.towers.length) for (const pad of pads.slice(0, 4)) f.place('slinger', pad);
  for (const pad of pads) if (!f.state.towers.some(t => t.pad === pad) && f.state.money >= 50) f.place('slinger', pad);
  for (const t of f.state.towers) if (t.level < 2 && f.state.money >= 41) f.upgrade(t.pad);
};
const eightSlingersL3 = async () => {
  const f = window.__clayfront;
  const pads = [1, 2, 6, 7, 4, 5, 8, 9];
  if (!f.state.towers.length) for (const pad of pads.slice(0, 4)) f.place('slinger', pad);
  for (const pad of pads) if (!f.state.towers.some(t => t.pad === pad) && f.state.money >= 50) f.place('slinger', pad);
  for (const t of f.state.towers) if (t.level < 3) { const c = t.level === 1 ? 41 : 65; if (f.state.money >= c) f.upgrade(t.pad); }
};

(async () => {
  await sim('4 SPITTERS NO UPGRADES', fourSlingers);
  await sim('6 SPITTERS LVL2', sixSlingersL2);
  await sim('8 SPITTERS LVL3', eightSlingersL3);
