const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function inspect(page, label, shot) {
  const data = await page.evaluate(() => {
    const L = window.__clayfront.layout;
    const c = document.querySelector('canvas');
    const r = c.getBoundingClientRect();
    const portrait = L.key === 'portrait';
    const scale = portrait
      ? Math.min((innerWidth - 12) / L.w, (Math.max(72, document.querySelector('.topbar').getBoundingClientRect().bottom + 7) + 200 - Math.max(72, document.querySelector('.topbar').getBoundingClientRect().bottom + 7)) / L.h)
      : Math.min(r.width / L.w, r.height / L.h);
    // use exact same math as game for landscape
    let s = Math.min(r.width / L.w, r.height / L.h);
    let ox = (r.width - L.w * s) / 2;
    let oy = (r.height - L.h * s) / 2 - (!portrait && innerHeight < 560 ? 20 : 0);
    if (portrait) {
      const top = Math.max(72, document.querySelector('.topbar').getBoundingClientRect().bottom + 7);
      const bottom = Math.max(top + 200, document.querySelector('#dock').getBoundingClientRect().top - 8);
      s = Math.min((innerWidth - 12) / L.w, (bottom - top) / L.h);
      ox = 6 + ((innerWidth - 12) - L.w * s) / 2;
      oy = top + ((bottom - top) - L.h * s) / 2;
    }
    const pads = L.pads.map(p => {
      const x = ox + p.x * s, y = oy + p.y * s;
      const el = document.elementFromPoint(x, y);
      return { i: p.i, x: Math.round(x), y: Math.round(y), hit: el ? (el.id || el.className || el.tagName) : null, free: el === c };
    });
    const dock = document.querySelector('#dock').getBoundingClientRect();
    const top = document.querySelector('.topbar').getBoundingClientRect();
    return { layout: L.key, scale: +s.toFixed(3), ox: Math.round(ox), oy: Math.round(oy), dock: { top: Math.round(dock.top), h: Math.round(dock.height) }, topbar: { bottom: Math.round(top.bottom) }, pads, allFree: pads.every(p => p.free) };
  });
  console.log(label, JSON.stringify(data));
  if (shot) await page.screenshot({ path: shot });
  return data;
}

(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart');
  await sleep(300);
  await inspect(page, 'DESKTOP', 'screenshots/desktop-dock.png');

  await page.setViewportSize({ width: 844, height: 390 });
  await sleep(500);
  const d = await inspect(page, 'LANDSCAPE', 'screenshots/mobile-landscape2.png');
  // try building on pad 6 with real click
  await page.evaluate(() => window.__clayfront.setClay(400));
  const ptPad = d.pads.find(p => p.i === 6);
  await page.locator('.tower-card').nth(0).click();
  await page.mouse.click(ptPad.x, ptPad.y);
  await sleep(250);
  console.log('LANDSCAPE BUILD pad6', await page.evaluate(() => ({ towers: window.__clayfront.state.towers.map(t => t.pad), money: window.__clayfront.state.money })));
  await inspect(page, 'LANDSCAPE AFTER BUILD', 'screenshots/mobile-landscape-built.png');

  await page.setViewportSize({ width: 390, height: 844 });
  await sleep(500);
  await inspect(page, 'PORTRAIT', 'screenshots/mobile-portrait2.png');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

