const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = []; page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart'); await sleep(150);
  const buy = async () => {
    await page.evaluate(() => {
      const f = window.__clayfront; const order = [1, 2, 6, 7, 4, 5, 8, 9, 0, 3, 10, 11];
      let acted = true;
      while (acted) {
        acted = false;
        for (const pad of order) {
          if (!f.state.towers.some(t => t.pad === pad) && f.state.money >= 50) { f.place('slinger', pad); acted = true; }
        }
        const t = f.state.towers.find(t => t.level < 3);
        if (t) { const c = t.level === 1 ? 41 : 65; if (f.state.money >= c) { f.upgrade(t.pad); acted = true; } }
        if (f.state.towers.length >= 12 && f.state.towers.every(t => t.level >= 3)) break;
      }
    });
  };
  await buy();
  for (let w = 0; w < 10; w++) {
    const s = await page.evaluate(() => window.__clayfront.stateSnapshot());
    if (s.mode === 'ended') break;
    await page.evaluate(() => window.__clayfront.startWave());
    for (let k = 0; k < 80; k++) {
      await page.evaluate(() => window.__clayfront.fastForward(2));
      const st = await page.evaluate(() => window.__clayfront.stateSnapshot());
      if (st.mode !== 'playing' || st.phase !== 'active') break;
    }
    await buy();
  }
  await sleep(800);
  console.log(await page.evaluate(() => ({ title: document.querySelector('#resultTitle').textContent, waves: document.querySelector('#resultWaves').textContent, kills: document.querySelector('#resultKills').textContent, towers: document.querySelector('#resultTowers').textContent, core: document.querySelector('#resultCore').textContent, best: document.querySelector('#resultBest').textContent })));
  console.log('errors', errors);
  await page.screenshot({ path: 'screenshots/desktop-victory.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

