const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = []; page.on('pageerror', e => errors.push(e.stack));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.click('#btnStart'); await sleep(150);
  const buy = async () => page.evaluate(() => {
    const f = window.__clayfront;
    const plan = { 0: 'kiln', 1: 'mortar', 2: 'slinger', 3: 'goo', 4: 'kiln', 5: 'slinger', 6: 'mortar', 7: 'goo', 8: 'slinger', 9: 'kiln', 10: 'mortar', 11: 'goo' };
    let acted = true;
    while (acted) {
      acted = false;
      for (const [pad, type] of Object.entries(plan)) {
        const p = +pad;
        if (!f.state.towers.some(t => t.pad === p)) {
          const cost = { slinger: 50, mortar: 85, goo: 65, kiln: 125 }[type];
          if (f.state.money >= cost) { f.place(type, p); acted = true; }
        }
      }
      for (const t of f.state.towers) {
        if (t.level < 3) {
          const base = { slinger: 50, mortar: 85, goo: 65, kiln: 125 }[t.type];
          const c = t.level === 1 ? Math.round(base * .82) : Math.round(base * 1.3);
          if (f.state.money >= c) { f.upgrade(t.pad); acted = true; break; }
        }
      }
    }
  });
  await buy();
  const logs = [];
  for (let w = 0; w < 10; w++) {
    const s = await page.evaluate(() => window.__clayfront.stateSnapshot());
    if (s.mode === 'ended') break;
    await page.evaluate(() => window.__clayfront.startWave());
    for (let k = 0; k < 80; k++) {
      await page.evaluate(() => window.__clayfront.fastForward(2));
      const st = await page.evaluate(() => window.__clayfront.stateSnapshot());
      if (st.mode !== 'playing' || st.phase !== 'active') break;
    }
    const st = await page.evaluate(() => window.__clayfront.stateSnapshot());
    logs.push(`w${w + 1} core${st.coreHp} kills${st.kills} tw${st.towers} money${st.money}${st.mode === 'ended' ? ' END' : ''}`);
    await buy();
  }
  const res = await page.evaluate(() => ({ title: document.querySelector('#resultTitle').textContent, shown: !document.querySelector('#resultOverlay').classList.contains('hidden'), s: window.__clayfront.stateSnapshot() }));
  console.log(logs.join(' | '));
  console.log('RESULT', JSON.stringify(res));
  console.log('ERRORS', errors.slice(0, 2));
  // screenshot a fresh mid-wave with all four tower types
  await page.click('#btnAgain'); await sleep(200);
  await page.evaluate(() => window.__clayfront.setClay(1600));
  for (const [pad, type] of [[1,'slinger'],[2,'mortar'],[6,'goo'],[7,'kiln'],[4,'slinger'],[5,'mortar'],[8,'goo'],[9,'kiln'],[0,'slinger'],[3,'mortar'],[10,'goo'],[11,'kiln']]) {
    await page.evaluate(({pad,type}) => window.__clayfront.place(type,pad), {pad,type});
  }
  await page.evaluate(() => window.__clayfront.fastForward(1));
  await page.evaluate(() => window.__clayfront.startWave());
  await page.evaluate(() => window.__clayfront.fastForward(8));
  await page.screenshot({ path: 'screenshots/desktop-mixed-towers.png' });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
