const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const EXE = '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';

const sizes = [
  { name: 'desktop-1440', w: 1440, h: 900 },
  { name: 'laptop-1280', w: 1280, h: 720 },
  { name: 'tablet-portrait', w: 834, h: 1112 },
  { name: 'tablet-landscape', w: 1112, h: 834 },
  { name: 'iphone14', w: 390, h: 844 },
  { name: 'iphone-se', w: 375, h: 667 },
  { name: 'android', w: 360, h: 740 },
  { name: 'small-landscape', w: 740, h: 360 }
];

(async () => {
  const browser = await chromium.launch({ executablePath: EXE, headless: true, args: ['--no-sandbox'] });
  for (const s of sizes) {
    const context = await browser.newContext({ viewport: { width: s.w, height: s.h }, hasTouch: true, isMobile: s.w < 900, deviceScaleFactor: 1 });
    const page = await context.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    await sleep(300);
    const menuOk = await page.locator('#menuOverlay').isVisible();
    await page.locator('#btnStart').tap();
    await sleep(300);
    const info = await page.evaluate(() => {
      const L = window.__clayfront.layout;
      const c = document.querySelector('canvas');
      const r = c.getBoundingClientRect();
      const portrait = L.key === 'portrait';
      let scale, ox, oy;
      if (portrait) {
        const top = Math.max(72, document.querySelector('.topbar').getBoundingClientRect().bottom + 7);
        const bottom = Math.max(top + 200, document.querySelector('#dock').getBoundingClientRect().top - 8);
        scale = Math.min((innerWidth - 12) / L.w, (bottom - top) / L.h);
        ox = 6 + ((innerWidth - 12) - L.w * scale) / 2;
        oy = top + ((bottom - top) - L.h * scale) / 2;
      } else {
        scale = Math.min(r.width / L.w, r.height / L.h);
        ox = (r.width - L.w * scale) / 2;
        oy = (r.height - L.h * scale) / 2 - (innerHeight < 560 ? 20 : 0);
      }
      const pads = L.pads.map(p => {
        const x = ox + p.x * scale, y = oy + p.y * scale;
        const el = document.elementFromPoint(x, y);
        return { i: p.i, x, y, free: el === c };
      });
      return {
        layout: L.key, scale: +scale.toFixed(3),
        dock: Math.round(document.querySelector('#dock').getBoundingClientRect().top),
        padsFree: pads.filter(p => p.free).length, padsTotal: pads.length,
        overflow: document.documentElement.scrollHeight > innerHeight + 1,
        firstPad: { x: Math.round(pads[0].x), y: Math.round(pads[0].y) }
      };
    });
    // tap-build on first pad
    await page.locator('.tower-card').nth(0).tap();
    await page.touchscreen.tap(info.firstPad.x, info.firstPad.y);
    await sleep(300);
    const built = await page.evaluate(() => window.__clayfront.state.towers.length);
    console.log(`${s.name} ${s.w}x${s.h} menu=${menuOk} layout=${info.layout} scale=${info.scale} dockTop=${info.dock} pads=${info.padsFree}/${info.padsTotal} overflow=${info.overflow} touchBuilt=${built} errors=${errors.length}`);
    if (built !== 1) console.log('  FAIL details', JSON.stringify(info), errors.slice(0, 2));
    await page.screenshot({ path: `screenshots/resp-${s.name}.png` });
    await context.close();
  }
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

