// ── State ────────────────────────────────────────────────────

function blankState(mode = 'menu') {
  return {
    mode,
    money: 240,
    coreHp: 20,
    coreMax: 20,
    waveIndex: 0,
    phase: 'prep',
    prepTimer: 14,
    prepDuration: 14,
    waveClock: 0,
    spawnCursor: 0,
    enemies: [],
    towers: [],
    projectiles: [],
    effects: [],
    particles: [],
    texts: [],
    kills: 0,
    built: 0,
    clayEarned: 0,
    quakeCd: 0,
    rallyCd: 0,
    rallyTimer: 0,
    shake: 0,
    coreFlash: 0,
    tutorial: true,
    won: false,
    nextId: 1,
    targetMode: null,
    speed: 1,
    bossAlive: false
  };
}

function createMenuState() {
  const state = blankState('menu');
  const picks = [[2, 'kiln', 3], [4, 'mortar', 2], [8, 'goo', 2], [10, 'slinger', 2]];
  for (const [padIndex, type, level] of picks) {
    const pad = layout.pads[padIndex];
    if (!pad) continue;
    state.towers.push({
      id: state.nextId++,
      pad: padIndex,
      x: pad.x,
      y: pad.y,
      type,
      level,
      angle: -.6 + Math.random() * .5,
      recoil: 0,
      attackCd: 1,
      spent: TOWERS[type].cost,
      scaleIn: 1,
      seed: Math.random() * TAU,
      rally: 0,
      demo: true
    });
  }
  return state;
}

function padOccupant(padIndex) {
  return game.towers.find(t => t.pad === padIndex);
}

function findPad(x, y) {
  let best = null;
  let bestD = Infinity;
  for (const pad of layout.pads) {
    const d = dist(x, y, pad.x, pad.y);
    if (d < layout.padRadius + 16 && d < bestD) {
      best = pad;
      bestD = d;
    }
  }
  return best;
}

