const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function fps(page, ms = 2000) {
  return page.evaluate((ms) => new Promise(resolve => {
    let frames = 0; const start = performance.now(); const times = []; let last = start;
    function tick(now) {
      frames++; times.push(now - last); last = now;
      if (now - start < ms) requestAnimationFrame(tick);
      else { times.sort((a, b) => a - b); resolve({ avgFps: +(frames / ((now - start) / 1000)).toFixed(1), p95: +times[Math.floor(times.length * .95)].toFixed(1) }); }
    }
    requestAnimationFrame(tick);
  }), ms);
}
